  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Doxazosin, the closest analogue (Morgan 0.5882), shares the 6,7-dimethoxy-4-aminoquinazoline core with a piperazine amide and has human oral bioavailability of 60-70%, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Bunazosin, a close analogue (Morgan 0.5873) with the same quinazoline-piperazine scaffold, showed absolute oral bioavailability of 44.1% in volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Trimazosin, sharing the same quinazoline core, demonstrated oral bioavailability of 61 ± 28% in normotensive volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Alfuzosin, a related quinazoline alpha-blocker, had a mean oral bioavailability of 64% in healthy volunteers, supporting high oral bioavailability for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Carbazeran, a more distant carbamate analogue, had absolute oral bioavailability below 5% in humans, but its different scaffold and metabolic liabilities limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is prazosin, a 2-furoylpiperazinyl-6,7-dimethoxy-4-aminoquinazoline. The closest structural analogues (doxazosin, bunazosin, trimazosin, alfuzosin) all show human absolute oral bioavailability well above 20% (44-78%), strongly supporting a high F >= 20% prediction. The only low-F analogue (carbazeran) is structurally distant and has a different metabolic profile, so it does not overturn the consistent high-bioavailability evidence.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for prazosin itself is included in the provided evidence.",
    "Potential first-pass metabolism specific to the furan carbonyl moiety is not directly quantified, though close analogues with similar amide piperazine groups show high bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

